\begin{proof}
	Let $q\in (i\dd j]$ be the smallest value such that $\D[i,j]=\D[i,q]+\D[q,j]$.
	We consider four cases:
	\begin{enumerate}
		\item $q=j$. In this case, $\D[i,j] = \ED(S[i]S[j-1]) + \D[i+1,j-1]\ge \D[i+1,j-1]$.
		\item $q=j-1$. In this case, $\D[i,j] = \ED(S[i]S[j-2]) + \D[i+1,j-2]+\D[j-1,j] \ge \D[i+1,\allowbreak {j-2}]+\D[j-2,j-1] \ge \D[i+1,j-1]$.
		\item $q = i+1$. Let $r\in [q\dd j)$ be the largest value such that $\D[q,j]=\D[q,r]+\D[r,j]$.
		We consider two subcases:
		\begin{enumerate}
			\item $r = j-1$. In this case, $\D[i,j] = \D[i,i+1] + \D[i+1,j-1] + \D[j-1,j] \ge \D[i+1,j-1]$.
			\item $r < j-1$. In this case, $\D[i,j] = \D[i,i+1] + \D[i+1,r] + \ED(S[r]S[j-1]) + \D[r+1,j-1]
			\ge \D[i+1,r] + \D[r,r+1] + \D[r+1,j-1] \ge \D[i+1,j-1]$.
		\end{enumerate}
		\item $i+1 < q < j-1$. Again, let $r\in [q\dd j)$ be the largest value such that $\D[q,j]=\D[q,r]+\D[r,j]$.
		We consider two subcases:
		\begin{enumerate}
			\item $r = j-1$. In this case,  $\D[i,j] = \ED(S[i]S[q-1]) + \D[i+1,q-1] + \D[q,j-1] +\D[j-1,j]
			\ge \D[i+1,q-1]+ \D[q-1,q] + \D[q,j-1]\ge \D[i+1,j-1]$.
			\item $r < j-1$. In this case,  $\D[i,j] = \ED(S[i]S[q-1]) + \D[i+1,q-1] + \D[q,r] + \ED(S[r]S[j-1])
			+ \D[r+1,j-1] \ge \D[i+1,q-1] + \ED(S[q-1]S[r]) + \D[q,r] + \D[r+1,j-1] \ge \D[i+1,q-1]+\D[q-1,r+1]+\D[r+1,j-1]\ge \D[i+1,j-1]$, where $\ED(S[i]S[q-1]) + \ED(S[r]S[j-1]) \ge 1 \ge \ED(S[q-1]S[r])$ follows from the fact that $S[q-1]$ is an opening parenthesis or $S[r]$ is a closing parenthesis (otherwise, we would have $q,r\in (b\dd c)$, which contradicts $\D[i,q]\le k$ and $\D[r,j]\le k$ by \cref{claim:trapezoids} applied to $(b-2k,b,c,c+2k)$).
		\end{enumerate}
	\end{enumerate}
\end{proof}
